import { chromium } from 'playwright';

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 960, height: 720 } });
page.on('pageerror', (e) => console.log('PAGE_ERROR:', e.message));

await page.goto('http://localhost:5173', { waitUntil: 'networkidle' });
await page.waitForSelector('svg[role="img"]');

// Hover mid-chart to exercise crosshair + tooltip.
const box = await page.locator('svg[role="img"]').boundingBox();
await page.mouse.move(box.x + box.width * 0.62, box.y + box.height * 0.5);
await page.waitForTimeout(200);
await page.screenshot({ path: 'light.png' });

// Simulate the dark theme: Gravity UI applies theme via root class on <body>.
await page.evaluate(() => {
  document.body.className = document.body.className.replace(/g-root_theme_\w+/, 'g-root_theme_dark');
});
await page.waitForTimeout(200);
await page.screenshot({ path: 'dark.png' });

console.log('body class:', await page.evaluate(() => document.body.className));
await browser.close();
console.log('DONE');

